<template>
  <div class="dt-page">
    <div class="dt-toolbar b30-bar">
      <div class="b30-rks">
        <span class="b30-rks__label">RKS</span>
        <span class="b30-rks__value">{{ rksL[0] }}</span>
        <span class="b30-rks__detail">（{{ rksL[1] }}）</span>
      </div>
    </div>

    <div class="b30-list">
      <div class="card-grid" :style="gridStyle">
        <b30Card
          v-for="(item, index) in b30List"
          :key="index"
          :chart-info="item" @click="openSong(item[0])"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { ref, onMounted, computed } from 'vue'
import b30Card from '../../components/cards/b30Card.vue'
import { getB30 } from '../../api/levels.js'

const b30List = ref(null)
const rksL = ref([])

onMounted(async () => {
  try {
    const [b30Data,rksLData] = await getB30()
    b30List.value = b30Data
    rksL.value = rksLData
  } catch (error) {
    console.error('B30加载失败：', error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 3
  },
  gap: {
    type: Number,
    default: 0.2
  },
  gridWidth: {
    type: [Number, String],
    default: '100%'
  }
})

const gridStyle = computed(() => {
  return {
    width: typeof props.gridWidth === 'number' ? `${props.gridWidth}px` : props.gridWidth,
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
})
</script>

<style scoped>
.b30-list {
  margin-top: 0.2rem;
}

/* RKS 放在页头右侧：一行数字，标签小字 */
.b30-rks {
  display: flex;
  align-items: baseline;
  gap: 0.08rem;
  margin-top: 0.08rem;
}

.b30-rks__label {
  color: var(--dt-text-dim);
  font-size: var(--dt-font-size-sm);
  font-weight: 600;
  letter-spacing: 0.08em;
}

.b30-rks__value {
  font-family: var(--dt-font-family-display);
  font-size: 0.21rem;
  line-height: 1;
  color: var(--dt-text);
}

.b30-rks__detail {
  color: var(--dt-text-muted);
  font-size: var(--dt-font-size-sm);
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(var(--column-count), 1fr);
  gap: var(--gap-rem);
  box-sizing: border-box;
  margin: 0 auto;
  user-select: none;
}

.card-grid > * {
  width: 100% !important;
  flex-shrink: 0;
  box-sizing: border-box;
}
</style>
